// _tree_resetSlicePtrTree empties the []*Tree that x points at and resets every
// element of its capacity, which keeps its memory for the next decode.
func _tree_resetSlicePtrTree(x *[]*Tree) {
	s := (*x)[:cap(*x)]
	for k := range s {
		if s[k] != nil {
			s[k].Reset()
		}
	}
	*x = (*x)[:0]
}

// _tree_resetSliceTree empties the []Tree that x points at and resets every
// element of its capacity, which keeps its memory for the next decode.
func _tree_resetSliceTree(x *[]Tree) {
	s := (*x)[:cap(*x)]
	for k := range s {
		s[k].Reset()
	}
	*x = (*x)[:0]
}

// _tree_clonePtrTree returns a pointer to a copy of the value that x, a *Tree,
// points at, and nil for a nil x.
func _tree_clonePtrTree(x *Tree) *Tree {
	if x == nil {
		return nil
	}
	return x.CloneKanon()
}

// _tree_cloneSlicePtrTree returns a copy of x, a []*Tree, and nil for a nil x.
func _tree_cloneSlicePtrTree(x []*Tree) []*Tree {
	if x == nil {
		return nil
	}
	c := make([]*Tree, len(x))
	for k := range x {
		c[k] = _tree_clonePtrTree(x[k])
	}
	return c
}

// _tree_cloneSliceTree returns a copy of x, a []Tree, and nil for a nil x.
func _tree_cloneSliceTree(x []Tree) []Tree {
	if x == nil {
		return nil
	}
	c := make([]Tree, len(x))
	for k := range x {
		x[k].cloneKanon(&c[k])
	}
	return c
}

// _tree_cloneMapStringPtrTree returns a copy of x, a map[string]*Tree, and nil
// for a nil x.
func _tree_cloneMapStringPtrTree(x map[string]*Tree) map[string]*Tree {
	if x == nil {
		return nil
	}
	c := make(map[string]*Tree, len(x))
	for mk, mv := range x {
		c[strings.Clone(mk)] = _tree_clonePtrTree(mv)
	}
	return c
}

// _tree_cloneMapInt32Tree returns a copy of x, a map[int32]Tree, and nil for a
// nil x.
func _tree_cloneMapInt32Tree(x map[int32]Tree) map[int32]Tree {
	if x == nil {
		return nil
	}
	c := make(map[int32]Tree, len(x))
	for mk, mv := range x {
		var cv Tree
		mv.cloneKanon(&cv)
		c[mk] = cv
	}
	return c
}

// _tree_sizePtrTree returns the length of the encoding of x, a *Tree: its
// presence byte and the value that it points at.
func _tree_sizePtrTree(x *Tree) int {
	if x == nil {
		return 1
	}
	return 1 + wire.SizeBytes(x.SizeKanon())
}

// _tree_putPtrTree writes the encoding of x, a *Tree, into the end of buf,
// which has room for it, and returns its length.
func _tree_putPtrTree(buf []byte, x *Tree) int {
	i := len(buf)
	if x != nil {
		w, _ := x.encodeKanon(buf[:i])
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _tree_readPtrTree decodes the *Tree at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _tree_readPtrTree(dst **Tree, data []byte, slab string, off, depth int, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(Tree)
		*dst = x
	}
	i := 1
	l, n := wire.Uvarint(data[i:])
	if n <= 0 || uint64(len(data)-i-n) < l {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	i += n
	if depth < 1 {
		return 0, wire.DepthError("Tree", 0, off+i)
	}
	if err := x.decodeKanon(data[i:i+int(l)], slab, off+i, depth-1); err != nil {
		return 0, err
	}
	i += int(l)
	return i, nil
}
